const LOCATION_PINS = [
  { x: 22, y: 35, label: "NW District", ok: true },
  { x: 38, y: 28, label: "Midtown", ok: true },
  { x: 55, y: 42, label: "Eastside", ok: false },
  { x: 68, y: 30, label: "Harbor", ok: true },
  { x: 47, y: 58, label: "South Loop", ok: true },
  { x: 30, y: 62, label: "West End", ok: true },
  { x: 75, y: 55, label: "Bay Area", ok: true },
  { x: 18, y: 55, label: "Park Slope", ok: true },
];

const MapPin: React.FC<{
  x: number;
  y: number;
  ok: boolean;
  label: string;
  delay: number;
  frame: number;
  fps: number;
}> = ({ x, y, ok, label, delay, frame, fps: fpsVal }) => {
  const progress = spring({ frame, fps: fpsVal, delay, config: { damping: 200 } });
  const pulseScale = ok
    ? 1
    : 1 + 0.18 * Math.sin((frame - delay) * 0.18);
  const pulseOpacity = ok ? 1 : 0.7 + 0.3 * Math.sin((frame - delay) * 0.18);
  const color = ok ? COLORS.green : COLORS.red;

  return (
    <div
      style={{
        position: "absolute",
        left: `${x}%`,
        top: `${y}%`,
        transform: `translate(-50%, -100%) scale(${interpolate(progress, [0, 1], [0, ok ? 1 : pulseScale])})`,
        opacity: interpolate(progress, [0, 1], [0, pulseOpacity]),
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        gap: 6,
      }}
    >
      {/* Pin */}
      <div
        style={{
          width: ok ? 36 : 52,
          height: ok ? 36 : 52,
          borderRadius: "50%",
          backgroundColor: color,
          border: `3px solid ${ok ? "rgba(0,200,150,0.4)" : "rgba(239,68,68,0.5)"}`,
          boxShadow: ok
            ? `0 0 18px rgba(0,200,150,0.4)`
            : `0 0 32px rgba(239,68,68,0.7)`,
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        {!ok && (
          <span style={{ color: "#fff", fontSize: 22, fontWeight: 700 }}>!</span>
        )}
      </div>
      {/* Halo for bad pin */}
      {!ok && progress > 0.5 && (
        <div
          style={{
            position: "absolute",
            top: "50%",
            left: "50%",
            transform: "translate(-50%, -50%)",
            width: 80,
            height: 80,
            borderRadius: "50%",
            border: "2px solid rgba(239,68,68,0.3)",
            animation: "none",
            opacity: 0.5 + 0.5 * Math.sin(frame * 0.12),
          }}
        />
      )}
      {/* Label */}
      <div
        style={{
          fontSize: ok ? 22 : 26,
          fontWeight: ok ? 500 : 700,
          color: ok ? COLORS.muted : COLORS.red,
          whiteSpace: "nowrap",
          marginTop: 4,
        }}
      >
        {label}
      </div>
    </div>
  );
};

